"use client";

import { useState } from "react";
import type { ReactNode } from "react";
import { AppShell, Header, Sidebar } from "./talentflow";
import { ApplicationsView as ApplicationsPrototypeView } from "./applications-view";
import { InterviewsView as InterviewsPrototypeView } from "./interviews-view";
import type {
  ApplicationColumnViewModel,
  JobListingViewModel,
  WorkspacePageId,
} from "./workspace-types";

const jobs = ["Senior Frontend Developer", "Senior Frontend Engineer", "Product Designer", "Tech Lead / Senior Developer"];
const panel = "rounded-xl border border-[#e0e3e5] bg-white p-6 shadow-[0_2px_8px_rgba(15,23,42,.06)]";
const primary = "rounded-lg bg-gradient-to-r from-[#0062ff] to-[#38bdf8] px-4 py-2 text-sm font-bold text-white shadow-sm hover:-translate-y-0.5";
const secondary = "rounded-lg border border-[#c2c6d9] bg-white px-4 py-2 text-sm font-semibold text-[#004cca] hover:bg-[#dbe1ff]/40";

function PageFrame({ title, description, children }: { title: string; description: string; children: ReactNode }) {
  const isApplications = title === "ติดตามผู้สมัคร";
  const activePath = title === "ตำแหน่งงาน" ? "/jobs" : title === "ค้นหาผู้สมัคร" ? "/discovery" : title === "คัดกรองเรซูเม่" ? "/screening" : isApplications ? "/applications" : "/";
  return <AppShell><Sidebar activePath={activePath} /><Header /><main className={`mx-auto px-4 xl:ml-[260px] md:px-6 ${isApplications ? "max-w-none space-y-4 py-4" : "max-w-7xl space-y-6 py-6"}`}><div className={isApplications ? "flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between" : ""}><div>{!isApplications && <p className="text-xs font-bold uppercase tracking-widest text-[#004cca]">TalentFlow</p>}<h2 className={`${isApplications ? "text-2xl" : "mt-2 text-4xl"} font-serif`}>{title}</h2><p className="mt-1 text-sm text-[#565e74]">{description}</p></div></div>{children}</main></AppShell>;
}

function JobSelect({ value, onChange }: { value: string; onChange: (value: string) => void }) { return <label className="block text-sm font-semibold">ตำแหน่งงาน<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-2 block w-full rounded-lg border border-[#c2c6d9] bg-white px-3 py-2"><option value="">เลือกตำแหน่งงาน</option>{jobs.map((job) => <option key={job}>{job}</option>)}</select></label>; }

function JobsView() { const [message, setMessage] = useState(""); return <PageFrame title="ตำแหน่งงาน" description="สร้างและจัดการประกาศรับสมัครงาน"><div className="grid gap-6 xl:grid-cols-[1.4fr_1fr]"><section className={panel}><div className="mb-5 flex items-center justify-between"><h3 className="text-lg font-semibold">รายการตำแหน่งงาน</h3><div className="flex gap-2"><button className={secondary}>ทั้งหมด 24</button><button className={secondary}>เปิดรับ 12</button></div></div><div className="space-y-3">{[["Senior React Developer", "เปิดรับ", "ผู้สมัครใหม่ 12"], ["UX/UI Designer", "ฉบับร่าง", "แก้ไขล่าสุด 2 ชั่วโมงที่แล้ว"], ["Data Analyst", "ปิดรับ", "ผู้สมัครทั้งหมด 84"]].map(([name, status, detail]) => <article key={name} className="rounded-lg border border-[#e0e3e5] p-4 hover:border-[#004cca]"><div className="flex items-start justify-between"><div><h4 className="font-semibold">{name}</h4><p className="mt-1 text-sm text-[#565e74]">Engineering Department · กรุงเทพมหานคร</p></div><span className="rounded-full bg-[#dbe1ff] px-2 py-1 text-xs font-bold text-[#004cca]">{status}</span></div><div className="mt-4 border-t border-[#e0e3e5] pt-3 text-sm text-[#565e74]">{detail}</div></article>)}</div></section><section className={panel}><h3 className="text-lg font-semibold">สร้างตำแหน่งงาน</h3><p className="mt-1 text-sm text-[#565e74]">บันทึกเป็นฉบับร่างก่อนเปิดรับสมัครได้</p><label className="mt-5 block text-sm font-semibold">ชื่อตำแหน่ง<input className="mt-2 block w-full rounded-lg border border-[#c2c6d9] px-3 py-2" placeholder="เช่น Senior Developer" /></label><label className="mt-4 block text-sm font-semibold">แผนก<select className="mt-2 block w-full rounded-lg border border-[#c2c6d9] px-3 py-2"><option>เลือกแผนก</option><option>Engineering</option><option>Product</option></select></label><label className="mt-4 block text-sm font-semibold">รายละเอียดงาน<textarea className="mt-2 block w-full rounded-lg border border-[#c2c6d9] px-3 py-2" rows={4} /></label><button onClick={() => setMessage("บันทึกตำแหน่งงานเป็นฉบับร่างแล้ว")} className={`${primary} mt-5 w-full`}>บันทึกฉบับร่าง</button>{message && <p role="status" className="mt-3 rounded-lg bg-[#dbe1ff] p-3 text-sm">{message}</p>}</section></div></PageFrame>; }

void JobsView;
void ScreeningView;
void PrototypeScreeningView;
void ApplicationsView;
void InterviewsView;
void ApplicationsViewExact;
function PrototypeDiscoveryView() { const [job, setJob] = useState(""); const [message, setMessage] = useState(""); return <PageFrame title="ค้นหาผู้สมัคร" description="ค้นหาและประเมินผู้สมัครสำหรับตำแหน่งที่เลือก"><div className="mb-6 flex flex-col items-start justify-between gap-4 md:flex-row md:items-end"><div className="w-full max-w-xl"><JobSelect value={job} onChange={setJob} /></div><div className="flex gap-3"><button className={secondary}><span className="material-symbols-outlined mr-1 align-middle text-sm">tune</span>ตัวกรอง</button><button disabled={!job} onClick={() => setMessage("ค้นหาสำเร็จ กรุณาตรวจหลักฐานก่อนอนุมัติ")} className={`${primary} disabled:opacity-50`}><span className="material-symbols-outlined mr-1 align-middle text-sm">refresh</span>เริ่มค้นหา</button></div></div><article className="overflow-hidden rounded-xl border border-[#c2c6d9] bg-white shadow-sm"><header className="flex items-start justify-between border-b border-[#e0e3e5] bg-[#f2f4f6] p-6"><div className="flex items-center gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-full border-2 border-white bg-[#dae2fd] text-xl font-bold text-[#004cca] shadow-sm">กพ</div><div><h3 className="flex items-center gap-2 text-lg font-bold">กิตติพงษ์ วิริยะ <span className="material-symbols-outlined text-sm text-[#004cca]">verified</span></h3><p className="text-sm text-[#565e74]">Senior Frontend Developer · TechCorp</p><div className="mt-2 flex flex-wrap gap-2"><span className="rounded-full border border-[#005e80]/20 bg-[#c4e7ff]/40 px-2.5 py-0.5 text-xs font-semibold text-[#005e80]">React</span><span className="rounded-full border border-[#005e80]/20 bg-[#c4e7ff]/40 px-2.5 py-0.5 text-xs font-semibold text-[#005e80]">TypeScript</span><span className="rounded-full border border-[#005e80]/20 bg-[#c4e7ff]/40 px-2.5 py-0.5 text-xs font-semibold text-[#005e80]">System Design</span></div></div></div><div className="text-center"><div className="flex h-16 w-16 items-center justify-center rounded-full border-2 border-[#004cca] bg-[#dbe1ff]/50 text-2xl font-bold text-[#004cca]">94</div><p className="mt-1 text-xs font-semibold text-[#565e74]">คะแนนความเหมาะสม</p></div></header><div className="grid divide-y divide-[#e0e3e5] md:grid-cols-3 md:divide-x md:divide-y-0"><section className="p-6"><h4 className="flex items-center gap-2 font-semibold"><span className="material-symbols-outlined text-[#004cca]">fact_check</span>หลักฐานที่พบ</h4><ul className="mt-4 space-y-3 text-sm text-[#424656]"><li><span className="mr-2 text-[#22c55e]">✓</span>ประสบการณ์ตรง 5 ปีในการสร้างระบบด้วย React</li><li><span className="mr-2 text-[#22c55e]">✓</span>ผ่าน Technical Test ระดับยอดเยี่ยม 95%</li><li><span className="mr-2 text-[#22c55e]">✓</span>ร่วมพัฒนา Open Source ระดับองค์กร</li></ul></section><section className="bg-[#ffdad6]/20 p-6"><h4 className="flex items-center gap-2 font-semibold text-[#ba1a1a]"><span className="material-symbols-outlined">warning</span>ข้อควรตรวจสอบ</h4><ul className="mt-4 space-y-3 text-sm text-[#424656]"><li><span className="mr-2 text-[#ba1a1a]">!</span>ประสบการณ์จัดการทีมขนาดใหญ่ยังจำกัด</li><li><span className="mr-2 text-[#ba1a1a]">!</span>คาดหวังเงินเดือนสูงกว่าโครงสร้าง 10%</li></ul></section><section className="flex flex-col justify-center gap-3 bg-[#f2f4f6] p-6"><button onClick={() => setMessage("อนุมัติแล้วและส่งต่อไปขั้นตอนสัมภาษณ์")} className={`${primary} flex w-full items-center justify-center gap-2`}><span className="material-symbols-outlined text-sm">thumb_up</span>อนุมัติเพื่อสัมภาษณ์</button><button onClick={() => setMessage("พักผลลัพธ์ไว้ให้ HR ตรวจสอบ")} className={`${secondary} flex w-full items-center justify-center gap-2`}><span className="material-symbols-outlined text-sm">help</span>รอการตรวจสอบ</button><button onClick={() => setMessage("กรุณาระบุเหตุผลก่อนปฏิเสธ")} className="flex w-full items-center justify-center gap-2 rounded-lg border border-[#ba1a1a] px-4 py-2 text-sm font-semibold text-[#ba1a1a]"><span className="material-symbols-outlined text-sm">thumb_down</span>ปฏิเสธ</button></section></div></article>{message && <p role="status" className="mt-4 rounded-lg bg-[#dbe1ff] p-3 text-sm text-[#00174b]">{message}</p>}</PageFrame>; }
function PrototypeJobsView() {
  const [message, setMessage] = useState("");
  const listings: readonly JobListingViewModel[] = [["Senior React Developer", "เปิดรับ", "Engineering Department · กรุงเทพมหานคร (Hybrid)", "12", "3", "10 ต.ค. 2023"], ["UX/UI Designer", "ฉบับร่าง", "Product Team · เชียงใหม่ (Remote)", "", "", "แก้ไขล่าสุด 2 ชั่วโมงที่แล้ว"], ["Data Analyst", "ปิดรับ", "Data Science · กรุงเทพมหานคร (On-site)", "84", "1", "รับเข้าทำงานแล้ว 1 ตำแหน่ง"]];
  return <PageFrame title="จัดการตำแหน่งงาน" description="ดูแลและสร้างประกาศรับสมัครงานใหม่สำหรับองค์กรของคุณ"><div className="grid gap-6 xl:grid-cols-8"><section className="space-y-4 xl:col-span-5"><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#e0e3e5] bg-white p-3 shadow-sm"><div className="flex flex-wrap gap-2"><button className="rounded-full bg-[#0062ff] px-4 py-1.5 text-sm font-semibold text-white">ทั้งหมด (24)</button><button className={secondary}>เปิดรับ (12)</button><button className={secondary}>ฉบับร่าง (5)</button><button className={secondary}>ปิดรับ (7)</button></div><button className="flex items-center gap-1 text-sm font-semibold text-[#565e74]"><span className="material-symbols-outlined text-sm">filter_list</span>ตัวกรอง</button></div>{listings.map(([name, status, meta, fresh, interview, footer]) => <article key={name} className="group rounded-xl border border-[#e0e3e5] bg-white p-6 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-start justify-between"><div><div className="flex items-center gap-3"><h3 className="text-lg font-bold group-hover:text-[#004cca]">{name}</h3><span className={`rounded-full px-2.5 py-0.5 text-xs font-bold ${status === "เปิดรับ" ? "bg-[#dcfce7] text-[#166534]" : status === "ปิดรับ" ? "bg-[#ffdad6] text-[#93000a]" : "bg-[#e0e3e5] text-[#424656]"}`}>{status}</span></div><p className="mt-2 text-sm text-[#565e74]">{meta}</p></div><button aria-label={`เมนู ${name}`} className="text-[#565e74]"><span className="material-symbols-outlined">more_vert</span></button></div>{status === "ฉบับร่าง" ? <p className="mt-5 border-t border-[#e0e3e5] pt-4 text-sm text-[#565e74]"><span className="material-symbols-outlined mr-2 align-middle text-sm">edit_note</span>{footer}</p> : <div className="mt-5 grid grid-cols-3 gap-4 border-t border-[#e0e3e5] pt-4"><div><span className="block text-xs font-bold uppercase tracking-wide text-[#565e74]">ผู้สมัครใหม่</span><strong className="mt-1 block font-mono text-lg text-[#004cca]">{fresh}</strong></div><div><span className="block text-xs font-bold uppercase tracking-wide text-[#565e74]">กำลังสัมภาษณ์</span><strong className="mt-1 block font-mono text-lg">{interview}</strong></div><div><span className="block text-xs font-bold uppercase tracking-wide text-[#565e74]">ข้อมูลล่าสุด</span><span className="mt-1 block text-sm">{footer}</span></div></div>}</article>)}</section><section className={`${panel} h-fit xl:col-span-3 xl:sticky xl:top-24`}><h3 className="flex items-center gap-2 text-xl font-bold"><span className="material-symbols-outlined text-[#004cca]">add_box</span>สร้างตำแหน่งงานใหม่</h3><p className="mt-2 text-sm text-[#565e74]">บันทึกเป็นฉบับร่างก่อนเปิดรับสมัคร</p><label className="mt-5 block text-sm font-semibold">ชื่อตำแหน่ง<input className="mt-2 block w-full rounded-lg border border-[#c2c6d9] px-3 py-2" placeholder="เช่น Marketing Manager" /></label><label className="mt-4 block text-sm font-semibold">แผนก<select className="mt-2 block w-full rounded-lg border border-[#c2c6d9] px-3 py-2"><option>เลือกแผนก</option><option>Engineering</option><option>Marketing</option><option>Human Resources</option></select></label><div className="mt-4"><span className="block text-sm font-semibold">สถานะเริ่มต้น</span><div className="mt-2 grid grid-cols-2 gap-2"><label className="flex cursor-pointer items-center justify-center rounded-lg border border-[#004cca] bg-[#dbe1ff]/40 p-3 text-sm"><input type="radio" name="job-status" defaultChecked className="mr-2" />บันทึกร่าง</label><label className="flex cursor-pointer items-center justify-center rounded-lg border border-[#c2c6d9] p-3 text-sm"><input type="radio" name="job-status" className="mr-2" />เปิดรับสมัคร</label></div></div><label className="mt-4 block text-sm font-semibold">รายละเอียดงาน<textarea className="mt-2 block w-full resize-none rounded-lg border border-[#c2c6d9] px-3 py-2" rows={5} /></label><div className="mt-5 flex gap-3"><button className={`${secondary} flex-1`}>ยกเลิก</button><button onClick={() => setMessage("บันทึกตำแหน่งงานเป็นฉบับร่างแล้ว")} className={`${primary} flex-1`}>บันทึกข้อมูล</button></div>{message && <p role="status" className="mt-3 rounded-lg bg-[#dbe1ff] p-3 text-sm">{message}</p>}</section></div></PageFrame>;
}

function ScreeningView() { const [job, setJob] = useState(""); const [message, setMessage] = useState(""); return <PageFrame title="คัดกรองเรซูเม่" description="วิเคราะห์เรซูเม่โดยมี HR ตรวจสอบก่อนตัดสินใจ"><div className="grid gap-6 lg:grid-cols-2"><section className={panel}><h3 className="text-lg font-semibold">เริ่มการวิเคราะห์</h3><div className="mt-5"><JobSelect value={job} onChange={setJob} /></div><div className="mt-5 rounded-xl border-2 border-dashed border-[#c2c6d9] bg-[#f2f4f6] p-10 text-center"><span className="material-symbols-outlined text-4xl text-[#004cca]">upload_file</span><p className="mt-2 font-semibold">อัปโหลดเรซูเม่</p><p className="mt-1 text-sm text-[#565e74]">รองรับ PDF และ DOCX</p></div><button disabled={!job} onClick={() => setMessage("วิเคราะห์เสร็จแล้ว ผลลัพธ์พร้อมให้ HR ตรวจสอบ")} className={`${primary} mt-5 w-full disabled:opacity-50`}>เริ่มการวิเคราะห์</button></section><section className={panel}><div className="flex items-center justify-between"><h3 className="text-lg font-semibold">ผลการประเมิน</h3><span className="rounded-full bg-[#ffdad6] px-2 py-1 text-xs font-bold text-[#93000a]">รอ HR ตรวจสอบ</span></div><div className="mt-5 rounded-lg bg-[#dbe1ff]/50 p-5"><strong className="text-3xl text-[#004cca]">86</strong><p className="mt-1 text-sm">คะแนนความเหมาะสม</p></div><ul className="mt-5 space-y-3 text-sm"><li>✓ ทักษะตรงกับตำแหน่ง 8 จาก 10 รายการ</li><li>✓ ประสบการณ์ตรง 4 ปี</li><li>! ต้องตรวจสอบช่วงว่างงาน 6 เดือน</li></ul>{message && <p role="status" className="mt-5 rounded-lg bg-[#dbe1ff] p-3 text-sm">{message}</p>}</section></div></PageFrame>; }

function PrototypeScreeningView() { const [job, setJob] = useState(""); const [tab, setTab] = useState("อัปโหลดไฟล์"); const [message, setMessage] = useState(""); return <PageFrame title="คัดกรองเรซูเม่" description="เลือกตำแหน่งงาน แล้วอัปโหลดหรือวางข้อความเพื่อวิเคราะห์ความเหมาะสม"><div className="grid gap-6 lg:grid-cols-12"><section className="space-y-5 lg:col-span-5"><div className={panel}><div className="flex border-b border-[#e0e3e5]"><button onClick={() => setTab("อัปโหลดไฟล์")} className={`px-4 py-3 text-sm font-semibold ${tab === "อัปโหลดไฟล์" ? "border-b-2 border-[#004cca] text-[#004cca]" : "text-[#565e74]"}`}>อัปโหลดไฟล์</button><button onClick={() => setTab("วางข้อความ")} className={`px-4 py-3 text-sm font-semibold ${tab === "วางข้อความ" ? "border-b-2 border-[#004cca] text-[#004cca]" : "text-[#565e74]"}`}>วางข้อความ</button></div><div className="mt-5"><JobSelect value={job} onChange={setJob} /></div>{tab === "อัปโหลดไฟล์" ? <div className="mt-5 rounded-xl border-2 border-dashed border-[#c2c6d9] bg-[#f2f4f6] p-10 text-center"><span className="material-symbols-outlined text-5xl text-[#004cca]">upload_file</span><h3 className="mt-3 font-semibold">ลากไฟล์มาวางที่นี่</h3><p className="mt-1 text-sm text-[#565e74]">หรือเลือกไฟล์ PDF / DOCX จากเครื่อง</p><button className={`${secondary} mt-5`}>เลือกไฟล์</button></div> : <textarea className="mt-5 block w-full rounded-lg border border-[#c2c6d9] p-4 text-sm" rows={9} placeholder="วางข้อความเรซูเม่ที่นี่..." />}<button disabled={!job} onClick={() => setMessage("วิเคราะห์เสร็จแล้ว ผลลัพธ์พร้อมให้ HR ตรวจสอบ")} className={`${primary} mt-5 w-full disabled:opacity-50`}><span className="material-symbols-outlined mr-1 align-middle text-sm">smart_toy</span>เริ่มการวิเคราะห์</button></div></section><section className="lg:col-span-7"><div className={panel}><div className="flex items-center justify-between border-b border-[#e0e3e5] pb-4"><h3 className="text-lg font-semibold">ผลการประเมิน</h3><span className="rounded-full bg-[#ffdad6] px-2 py-1 text-xs font-bold text-[#93000a]">รอ HR ตรวจสอบ</span></div><div className="mt-5 flex flex-wrap items-center justify-between gap-5 rounded-xl bg-[#f2f4f6] p-5"><div><span className="text-sm text-[#565e74]">คะแนนความเหมาะสม</span><strong className="mt-1 block font-serif text-5xl text-[#004cca]">86</strong></div><div className="text-sm text-[#565e74]">ตำแหน่ง: {job || "ยังไม่ได้เลือก"}</div></div><div className="mt-5 flex gap-4 border-b border-[#e0e3e5]"><button className="border-b-2 border-[#004cca] px-2 py-3 text-sm font-semibold text-[#004cca]">ผลการประเมิน</button><button className="px-2 py-3 text-sm text-[#565e74]">ข้อมูลที่ดึงได้</button></div><div className="mt-5 grid gap-5 md:grid-cols-2"><div><h4 className="font-semibold text-[#166534]">หลักฐานที่สนับสนุน</h4><ul className="mt-3 space-y-3 text-sm"><li>✓ ทักษะตรงกับตำแหน่ง 8 จาก 10 รายการ</li><li>✓ ประสบการณ์ตรง 4 ปี</li><li>✓ ผ่านเกณฑ์การศึกษา</li></ul></div><div><h4 className="font-semibold text-[#ba1a1a]">ข้อควรตรวจสอบ</h4><ul className="mt-3 space-y-3 text-sm"><li>! ต้องตรวจสอบช่วงว่างงาน 6 เดือน</li><li>! เงินเดือนคาดหวังสูงกว่าช่วงกลาง</li></ul></div></div><label className="mt-6 block text-sm font-semibold">เหตุผลของ HR (กรณีแก้ไขผล AI)<textarea className="mt-2 block w-full rounded-lg border border-[#c2c6d9] p-3" rows={3} placeholder="ระบุเหตุผลก่อนบันทึกการแก้ไข..." /></label><button onClick={() => setMessage("บันทึกผลการตรวจสอบและเหตุผลแล้ว")} className={`${secondary} mt-4`}>บันทึกข้อความ</button>{message && <p role="status" className="mt-4 rounded-lg bg-[#dbe1ff] p-3 text-sm">{message}</p>}</div></section></div></PageFrame>; }

function ScreeningEvidence() { const [message, setMessage] = useState(""); return <section className={`${panel} overflow-hidden p-0`}><div className="flex border-b border-[#e0e3e5] px-4"><button className="border-b-2 border-[#004cca] px-4 py-4 text-sm font-bold text-[#004cca]">ผลการประเมิน</button><button className="px-4 py-4 text-sm text-[#565e74]">ข้อมูลที่ดึงได้</button></div><div className="space-y-6 p-6"><div><h4 className="flex items-center gap-2 font-semibold"><span className="material-symbols-outlined text-[#22c55e]">check_circle</span>จุดแข็ง</h4><div className="mt-3 space-y-3"><div className="flex items-start gap-3 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-3 text-sm"><span className="material-symbols-outlined mt-0.5 text-[20px] text-[#0f766e]">bolt</span><div><strong className="block">ความเชี่ยวชาญ Modern Tech Stack</strong>มีประสบการณ์สูงใน React และ JavaScript ตรงตามความต้องการหลัก</div></div><div className="flex items-start gap-3 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-3 text-sm"><span className="material-symbols-outlined mt-0.5 text-[20px] text-[#0f766e]">architecture</span><div><strong className="block">ประสบการณ์ออกแบบสถาปัตยกรรมระบบ</strong>เคยร่วมพัฒนาโปรเจกต์ขนาดใหญ่</div></div></div></div><div><h4 className="flex items-center gap-2 font-semibold text-[#ba1a1a]"><span className="material-symbols-outlined">warning</span>ความเสี่ยงที่พบ</h4><div className="mt-3 flex items-start gap-3 rounded-lg border border-[#ffdad6] bg-[#ffdad6]/30 p-3 text-sm"><span className="material-symbols-outlined mt-0.5 text-[20px] text-[#ba1a1a]">history_toggle_off</span><div><strong className="block">อายุงานสั้นในที่ทำงานล่าสุด</strong>ทำงานที่บริษัทล่าสุดเพียง 8 เดือน ควรสอบถามเหตุผลในการสัมภาษณ์</div></div></div><div className="border-t border-[#e0e3e5] pt-5"><h4 className="flex items-center gap-2 font-semibold"><span className="material-symbols-outlined text-[#565e74]">edit_note</span>ปรับแก้ผลการประเมิน (Override)</h4><textarea className="mt-3 block w-full resize-none rounded-lg border border-[#c2c6d9] p-3 text-sm" rows={3} placeholder="ระบุเหตุผลหากต้องการปรับเปลี่ยนคะแนนหรือสถานะที่ AI ประเมินไว้..." /><button onClick={() => setMessage("บันทึกข้อความพร้อม audit log แล้ว")} className={`${secondary} mt-3`}>บันทึกข้อความ</button></div>{message && <p role="status" className="rounded-lg bg-[#dbe1ff] p-3 text-sm">{message}</p>}</div></section>; }

function ApplicationsView() { const [stage, setStage] = useState("คัดกรองเบื้องต้น"); const columns: readonly ApplicationColumnViewModel[] = [{ title: "สมัครใหม่", count: 12, dot: "bg-[#94a3b8]", cards: [{ name: "วิชญะ อารีรัตน์", initials: "ว", experience: "3 ปีประสบการณ์", time: "วันนี้", tags: ["React", "Tailwind"] }, { name: "ณัฐกานต์ วงศ์สว่าง", initials: "ณ", experience: "5 ปีประสบการณ์", time: "เมื่อวาน", tags: ["Vue.js", "Figma"] }] }, { title: "คัดกรองเบื้องต้น", count: 5, dot: "bg-[#f59e0b]", cards: [{ name: "ธนโชติ วงศ์วิวัฒน์", initials: "ชน", experience: "4 ปีประสบการณ์", badge: "รอติดต่อ", detail: "ผู้สมัครมีทักษะ React แข็งแกร่ง แต่ต้องการเงินเดือนสูงกว่าโครงสร้างเล็กน้อย...", time: "อัปเดท 1 ชม. ที่แล้ว" }] }, { title: "สัมภาษณ์", count: 3, dot: "bg-[#0f766e]", cards: [{ name: "นภัสสร รุ่งเรือง", initials: "น", experience: "6 ปีประสบการณ์", interview: "พรุ่งนี้, 14:00 น.", time: "ผู้สัมภาษณ์: CTO" }] }, { title: "ข้อเสนอ/รับเข้าทำงาน", count: 1, dot: "bg-[#64748b]", cards: [{ name: "ธนพล สุขสันต์", initials: "ธ", experience: "Frontend Lead • รอเซ็นสัญญา", hired: true }] }]; return <PageFrame title="ติดตามผู้สมัคร" description="ตรวจสอบผู้สมัคร เปลี่ยนขั้นตอน และบันทึกการตัดสินใจของ HR"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center rounded-lg bg-[#e8edf2] p-1"><button className={`${primary} flex items-center gap-2 px-3 py-1.5`}><span className="material-symbols-outlined text-[18px]">dashboard</span>บอร์ด</button><button className="flex items-center gap-2 px-3 py-1.5 text-sm text-[#565e74]"><span className="material-symbols-outlined text-[18px]">format_list_bulleted</span>รายการ</button></div><div className="flex flex-wrap gap-3"><JobSelect value="Senior Frontend Engineer" onChange={() => undefined} /><button className={secondary}><span className="material-symbols-outlined mr-1 align-middle text-sm">calendar_today</span>สัปดาห์นี้</button><button className={secondary}><span className="material-symbols-outlined mr-1 align-middle text-sm">filter_list</span>ตัวกรองเพิ่มเติม</button></div></div><div className="mt-2 flex gap-6 overflow-x-auto pb-4">{columns.map((column) => <section key={column.title} className="flex min-h-[430px] w-80 shrink-0 flex-col rounded-xl border border-[#d9dee7] bg-[#eef2f5] p-3"><header className="mb-4 flex items-center justify-between px-2"><h3 className="flex items-center gap-2 font-semibold"><span className={`h-2.5 w-2.5 rounded-full ${column.dot}`} />{column.title}</h3><span className="rounded-full bg-[#dce2e8] px-2 py-0.5 text-xs text-[#565e74]">{column.count}</span></header><div className="flex-1 space-y-3">{column.cards.map((card) => <article key={card.name} onClick={() => setStage(column.title)} className={`cursor-pointer rounded-lg border bg-white p-4 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md ${stage === column.title ? "border-[#004cca]" : "border-[#d9dee7]"}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#dbe1ff] text-sm font-bold text-[#004cca]">{card.initials}</div><div><h4 className="font-semibold">{card.name}</h4><p className="text-xs text-[#565e74]">{card.experience}</p></div></div>{card.time && <span className="text-[10px] text-[#8a93a6]">{card.time}</span>}</div>{card.tags && <div className="mt-3 flex flex-wrap gap-1.5">{card.tags.map((tag) => <span key={tag} className="rounded bg-[#e8edf2] px-2 py-0.5 text-[10px] text-[#565e74]">{tag}</span>)}</div>}{card.badge && <div className="mt-3 flex items-center gap-1 rounded border border-[#f5d58a] bg-[#fff8e6] px-2 py-1 text-[10px] text-[#9a6700]"><span className="material-symbols-outlined text-[12px]">call</span>{card.badge}</div>}{card.detail && <p className="mt-2 line-clamp-2 text-sm text-[#565e74]">{card.detail}</p>}{card.interview && <div className="mt-3 flex items-center gap-2 rounded-md border border-[#b8e3d8] bg-[#e8f8f3] p-2 text-xs text-[#0f766e]"><span className="material-symbols-outlined text-[16px]">event</span>{card.interview}</div>}{card.hired && <span className="material-symbols-outlined float-right text-sm text-[#0f766e]">check_circle</span>}{(card.detail || card.interview) && <div className="mt-3 border-t border-[#e0e3e5] pt-2 text-[10px] text-[#8a93a6]">{card.time}</div>}</article>)}</div></section>)}</div></PageFrame>; }

function InterviewsView() { const [message, setMessage] = useState(""); return <PageFrame title="ตารางนัดสัมภาษณ์" description="สร้างนัดหมายโดยตรวจสอบเวลาชนก่อนเสมอ"><section className={panel}><div className="flex items-center justify-between"><div><h3 className="text-lg font-semibold">สัปดาห์นี้</h3><p className="mt-1 text-sm text-[#565e74]">4 นัดหมาย · 1 รายการต้องติดตาม</p></div><button onClick={() => setMessage("เลือกผู้สมัครและเวลาที่ต้องการนัดหมาย")} className={primary}>นัดหมายใหม่</button></div><div className="mt-6 space-y-3"><article className="flex items-center justify-between rounded-lg border border-[#e0e3e5] p-4"><div><b>วันนี้ · 10:00–10:30</b><p className="mt-1 text-sm text-[#565e74]">Narin Chaiyapruk · Tech Lead</p></div><button onClick={() => setMessage("เวลานี้ไม่ว่าง กรุณาเลือกเวลาใหม่")} className="rounded-lg border border-[#ba1a1a] px-3 py-2 text-sm font-semibold text-[#ba1a1a]">เลื่อนเวลา</button></article></div>{message && <p role="status" className="mt-4 rounded-lg bg-[#ffdad6] p-3 text-sm text-[#93000a]">{message}</p>}</section></PageFrame>; }

function SettingsView() { const [saved, setSaved] = useState(false); return <PageFrame title="ตั้งค่าพื้นที่ทำงาน" description="จัดการการแจ้งเตือน สิทธิ์ และการเชื่อมต่อ"><div className="grid gap-6 md:grid-cols-2"><section className={panel}><h3 className="text-lg font-semibold">การแจ้งเตือน</h3><p className="mt-1 text-sm text-[#565e74]">เลือกเหตุการณ์ที่ต้องการให้ HR รับการแจ้งเตือน</p><label className="mt-5 flex gap-3 text-sm"><input type="checkbox" defaultChecked /> มีเรซูเม่รอตรวจสอบ</label><label className="mt-3 flex gap-3 text-sm"><input type="checkbox" defaultChecked /> เวลาสัมภาษณ์ชนกัน</label></section><section className={panel}><h3 className="text-lg font-semibold">สิทธิ์และการเชื่อมต่อ</h3><p className="mt-1 text-sm text-[#565e74]">การเปลี่ยนแปลงสำคัญต้องมีเหตุผลและ audit log</p><button onClick={() => setSaved(true)} className={`${primary} mt-5`}>บันทึกการตั้งค่า</button>{saved && <p role="status" className="mt-3 text-sm text-[#166534]">บันทึกการตั้งค่าแล้ว</p>}</section></div></PageFrame>; }

function HelpView() { return <PageFrame title="ศูนย์ช่วยเหลือ" description="คำแนะนำและแนวทางแก้ไขปัญหาตาม workflow"><div className="space-y-4">{[["เริ่มต้นใช้งานอย่างไร", "เริ่มจาก Dashboard แล้วเลือกงานที่ต้องทำ จากนั้นทำงานตาม context ของแต่ละหน้า"], ["ถ้า AI ล้มเหลวทำอย่างไร", "ตรวจสอบ error code แล้วกดลองใหม่ ระบบต้องใช้ idempotency key เดิมและไม่สร้างข้อมูลซ้ำ"], ["ถ้าเวลาสัมภาษณ์ชนกันทำอย่างไร", "ระบบจะไม่สร้างนัดหมาย ให้เลือกเวลาใหม่หรือเลื่อนไปวันอื่น"]].map(([title, detail]) => <details key={title} open className={panel}><summary className="cursor-pointer font-semibold">{title}</summary><p className="mt-3 text-sm text-[#565e74]">{detail}</p></details>)}</div></PageFrame>; }

function ScreeningEvidenceInteractive() {
  const [activeTab, setActiveTab] = useState<"scorecard" | "extracted">("scorecard");
  const [overrideReason, setOverrideReason] = useState("");
  const [saveMessage, setSaveMessage] = useState("");
  const tabs = [
    ["scorecard", "ผลการประเมิน (Scorecard)"],
    ["extracted", "ข้อมูลที่ดึงได้ (Extracted)"],
  ] as const;
  const saveOverride = () => {
    setSaveMessage(overrideReason.trim() ? "บันทึกข้อความพร้อม audit log แล้ว" : "กรุณาระบุเหตุผลก่อนบันทึกข้อความ");
  };

  return <section className={`${panel} overflow-hidden p-0`}>
    <div role="tablist" aria-label="รายละเอียดผลการคัดกรอง" className="flex border-b border-[#e0e3e5] px-4">
      {tabs.map(([tab, label]) => <button key={tab} id={`screening-tab-${tab}`} type="button" role="tab" aria-selected={activeTab === tab} aria-controls={`screening-panel-${tab}`} onClick={() => setActiveTab(tab)} className={`px-4 py-4 text-sm ${activeTab === tab ? "border-b-2 border-[#004cca] font-bold text-[#004cca]" : "text-[#565e74]"}`}>{label}</button>)}
    </div>
    <div id={`screening-panel-${activeTab}`} role="tabpanel" aria-labelledby={`screening-tab-${activeTab}`} className="space-y-6 p-6">
      {activeTab === "scorecard" ? <>
        <div>
          <h4 className="flex items-center gap-2 font-semibold"><span aria-hidden="true" className="material-symbols-outlined text-[#22c55e]">check_circle</span>จุดแข็ง</h4>
          <div className="mt-3 space-y-3"><div className="flex items-start gap-3 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-3 text-sm"><span aria-hidden="true" className="material-symbols-outlined mt-0.5 text-[20px] text-[#0f766e]">bolt</span><div><strong className="block">ความเชี่ยวชาญ Modern Tech Stack</strong>มีประสบการณ์สูงใน React และ JavaScript ตรงตามความต้องการหลัก</div></div><div className="flex items-start gap-3 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-3 text-sm"><span aria-hidden="true" className="material-symbols-outlined mt-0.5 text-[20px] text-[#0f766e]">architecture</span><div><strong className="block">ประสบการณ์ออกแบบสถาปัตยกรรมระบบ</strong>เคยร่วมพัฒนาโปรเจกต์ขนาดใหญ่</div></div></div>
        </div>
        <div>
          <h4 className="flex items-center gap-2 font-semibold text-[#ba1a1a]"><span aria-hidden="true" className="material-symbols-outlined">warning</span>ความเสี่ยงที่พบ</h4>
          <div className="mt-3 flex items-start gap-3 rounded-lg border border-[#ffdad6] bg-[#ffdad6]/30 p-3 text-sm"><span aria-hidden="true" className="material-symbols-outlined mt-0.5 text-[20px] text-[#ba1a1a]">history_toggle_off</span><div><strong className="block">อายุงานสั้นในที่ทำงานล่าสุด</strong>ทำงานที่บริษัทล่าสุดเพียง 8 เดือน ควรสอบถามเหตุผลในการสัมภาษณ์</div></div>
        </div>
      </> : <div className="space-y-4 text-sm">
        <div><h4 className="font-semibold">ข้อมูลพื้นฐาน</h4><dl className="mt-3 grid gap-3 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-4 sm:grid-cols-2"><div><dt className="text-[#565e74]">ชื่อผู้สมัคร</dt><dd className="mt-1 font-medium">สมชาย ใจดี</dd></div><div><dt className="text-[#565e74]">อีเมล</dt><dd className="mt-1 font-medium">somchai@example.com</dd></div><div><dt className="text-[#565e74]">ตำแหน่งปัจจุบัน</dt><dd className="mt-1 font-medium">Senior Frontend Developer</dd></div><div><dt className="text-[#565e74]">ประสบการณ์รวม</dt><dd className="mt-1 font-medium">7 ปี</dd></div></dl></div>
        <div><h4 className="font-semibold">ทักษะที่ดึงได้</h4><p className="mt-2 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-4">React, TypeScript, Next.js, Tailwind CSS, System Design</p></div>
        <div><h4 className="font-semibold">การศึกษา</h4><p className="mt-2 rounded-lg border border-[#e0e3e5] bg-[#f2f4f6] p-4">ปริญญาตรี วิศวกรรมคอมพิวเตอร์ · 2016–2020</p></div>
      </div>}
      <div className="border-t border-[#e0e3e5] pt-5"><h4 className="flex items-center gap-2 font-semibold"><span aria-hidden="true" className="material-symbols-outlined text-[#565e74]">edit_note</span>ปรับแก้ผลการประเมิน (Override)</h4><textarea aria-label="เหตุผลสำหรับการปรับแก้ผลการประเมิน" value={overrideReason} onChange={(event) => { setOverrideReason(event.target.value); setSaveMessage(""); }} className="mt-3 block w-full resize-none rounded-lg border border-[#c2c6d9] p-3 text-sm" rows={3} placeholder="ระบุเหตุผลหากต้องการปรับเปลี่ยนคะแนนหรือสถานะที่ AI ประเมินไว้..." /><button type="button" onClick={saveOverride} className={`${secondary} mt-3`}>บันทึกข้อความ</button>{saveMessage && <p role="status" aria-live="polite" className="mt-3 rounded-lg bg-[#dbe1ff] p-3 text-sm">{saveMessage}</p>}</div>
    </div>
  </section>;
}

